      <b-card>
        <b-tabs active-nav-item-class="nav nav-tabs" content-class="mt-3">
          <b-tab title="Customer Information" active>
            <b-form @submit.prevent="update_customer_information()">
              <b-card title="Customer Information" class="shadow-none" style="border: none">
                <b-row>
                  <b-form-group class="col-md-6 mb-3" label="Full Name:" label-for="input-1">
                    <b-form-input v-model="customer_information.customer_name" type="text" required
                      placeholder="Full Name"></b-form-input>
                  </b-form-group>
                  <b-form-group class="col-md-6 mb-3" label="Email:" label-for="input-1">
                    <b-form-input v-model="customer_information.email_id" type="email"
                      placeholder="Email"></b-form-input>
                  </b-form-group>
                  <b-form-group class="col-md-6 mb-3" label="Phone Number:" label-for="input-1">
                    <b-form-input v-model="customer_information.mobile_no" type="text"
                      placeholder="Phone number"></b-form-input>
                  </b-form-group>
                  <b-form-group class="col-md-6 mb-3" label="Website:" label-for="input-1">
                    <b-form-input v-model="customer_information.website" type="text" required
                      placeholder="Website"></b-form-input>
                  </b-form-group>
                  <b-col md="12">
                    <b-button class="mt-3" type="submit" variant="primary">Update</b-button>
                  </b-col>
                </b-row>
              </b-card>
            </b-form>
          </b-tab>

          <b-tab title="Addresses">
            <b-card title="Address Information" class="shadow-none" style="border: none">
              <div v-if="isSkeletonLoaded">
                <Skeleton />
              </div>
              <b-container v-if="!isSkeletonLoaded">
                <b-row class="d-flex">
                  <b-col lg="6" sm="6" class="d-flex align-items-stretch">
                    <b-card no-body class="mb-30 w-100 card-icon-big text-center cursor-pointer justify-content-center"
                      style="
                        border: 2px dashed;
                        min-height: 215px;
                        margin-bottom: 30px !important;
                      " @click="OpenAddressModal(true)" text-variant>
                      <p class="card-text d-flex justify-content-center">
                        <img src="../../assets/Icons/Dashboard/add-address.png" />
                      </p>
                      <p class="line-height-1 text-title text-18 mt-2 mb-0">
                        New Address
                      </p>
                    </b-card>
                  </b-col>

                  <b-col lg="6" sm="6" class="d-flex align-items-stretch" v-for="(item, index) in address_list"
                    :key="index">
                    <b-card class="mb-30 w-100" style="margin-bottom: 30px !important">
                      <b-card-title>
                        <h4 data-v-e0193774="" class="card-title">
                          {{ item.address_title }}
                          <b-badge pill variant="outline-primary m-1">{{
                            item.address_type
                          }}</b-badge>
                          <b-badge v-if="customer_primary_address == item.name" pill
                            variant="outline-primary m-1">Default</b-badge>
                        </h4>
                      </b-card-title>
                      <b-card-text>
                        {{ item.address_line1 }} <br />
                        {{ item.address_line2 }} <br />
                        {{ item.city }} {{ item.state }} {{
                          item.pincode
                        }}<br />
                        {{ item.country }}
                        <span v-if="item.phone"><br />
                          Phone Number : 32515</span>
                      </b-card-text>
                      <a v-if="customer_primary_address != item.name" href="#"
                        @click.prevent="make_default_address(item.name)" class="card-link">Set Default</a>
                      <a href="#" @click.prevent="OpenAddressModal(false, item)" class="card-link">Edit</a>
                      <a href="#" @click.prevent="confirm_delete_address(item.name)" class="card-link">Delete</a>
                    </b-card>
                  </b-col>
                </b-row>
              </b-container>
            </b-card>
          </b-tab>

          <b-tab title="Change Password">
            <b-form @submit.prevent="update_password">
              <b-card title="Account Password" class="shadow-none" style="border: none">
                <b-row>
                  <b-form-group class="col-md-6 mb-3" label="Current Password:" label-for="input-1">
                    <b-form-input v-model="password_form.current_password" type="password" required
                      placeholder="Current Password"></b-form-input>
                  </b-form-group>
                  <b-form-group class="col-md-6 mb-3" label="New Password:" label-for="input-1">
                    <b-form-input v-model="password_form.new_password" type="password" required
                      placeholder="New Password"></b-form-input>
                  </b-form-group>

                  <b-col md="12">
                    <b-button class="mt-3" type="submit" variant="primary">Submit</b-button>
                  </b-col>
                </b-row>
              </b-card>
            </b-form>
          </b-tab>
        </b-tabs>
      </b-card>
    </b-card-group>
    <b-modal size="lg" ref="my-modal" hide-footer>
      <template #modal-title>
        <b> {{ add_address? "Add": "Edit" }} Address </b>
      </template>

      <div class="add-addres-modal">
        <div class="row">
          <div class="col-6">
            <!-- Address Start -->
            <div class="form-group mb-3">
              <label class="mb-2" for="AddressTitle">Address Title</label>
              <input type="text" class="form-control" name="AddressTitle" v-model="add_edit_address.address_title" />
            </div>
            <!-- Address End -->
          </div>
          <div class="col-6">
            <!-- Address Type Start -->
            <div class="form-group mb-3">
              <label class="mb-2" for="AddressType">Address type <span class="mandatory">*</span></label>
              <v-select required :options="['Billing', 'Shipping']" v-model="add_edit_address.address_type" />
            </div>
            <!-- Address Type End -->
          </div>
        </div>

        <div class="row">
          <div class="col-6">
            <!-- Address Line 1 Start -->
            <div class="form-group mb-3">
              <label class="mb-2" for="AddressLine1">Address Line 1 <span class="mandatory">*</span></label>
              <input type="text" class="form-control" name="AddressLine1" required
                v-model="add_edit_address.address_line1" />
            </div>
            <!-- Address Line End -->
          </div>
          <div class="col-6">
            <!-- Address Line 2 Start -->
            <div class="form-group mb-3">
              <label class="mb-2" for="AddressLine2">Address Line 2</label>
              <input type="text" class="form-control" name="AddressLine2" v-model="add_edit_address.address_line2" />
            </div>
            <!-- Address Line 2 End -->
          </div>
        </div>

        <div class="row">
          <div class="col-6">
            <!-- City/Town Start -->
            <div class="form-group mb-3">
              <label class="mb-2" for="CityTown">City/Town <span class="mandatory">*</span></label>
              <input type="text" class="form-control" name="CityTown" required v-model="add_edit_address.city" />
            </div>
            <!-- City/Town End -->
          </div>
          <div class="col-6">
            <!-- State/Province Start -->
            <div class="form-group mb-3">
              <label class="mb-2" for="StateProvince">State/Province</label>
              <input type="text" class="form-control" name="StateProvince" v-model="add_edit_address.state" />
            </div>
            <!-- State/Province End -->
          </div>
        </div>

        <div class="row">
          <div class="col-6">
            <!-- Country Start -->
            <div class="form-group mb-3">
              <label class="mb-2" for="Country">Country <span class="mandatory">*</span></label>
              <input type="text" class="form-control" name="Country" required v-model="add_edit_address.country" />
            </div>
            <!-- Country End -->
          </div>
          <div class="col-6">
            <!-- Postal Code Start -->
            <div class="form-group mb-3">
              <label class="mb-2" for="PostalCode">Postal Code</label>
              <input type="text" class="form-control" name="PostalCode" v-model="add_edit_address.pincode" />
            </div>
            <!-- Postal Code End -->
          </div>
        </div>
      </div>
      <div class="col-md-12 text-right">
        <b-button class="mt-3 save-address-modal" @click="CloseAddressModal()">Save</b-button>
      </div>
    </b-modal>
  </div>
</template>
<script>
import vSelect from "vue-select";
import BreadCrumb from "../../components/breadcrumbs.vue";
import Skeleton from "./profile_skeleton.vue";
import CommonApi from "@/services/CommonApi";

export default {
  name: "ProfilePage",
  components: {
    vSelect,
    BreadCrumb,
    Skeleton,
  },
  data() {
    return {
      customer_information: {
        customer_name: "",
        email_id: "",
        mobile_no: "",
        pan: "",
        website: "",
      },
      customer_primary_address: "",
      password_form: {
        current_password: "",
        new_password: "",
      },
      add_address: true,
      add_edit_address: {
        name: "",
        address_title: "",
        address_type: "",
        address_line1: "",
        address_line2: "",
        city: "",
        state: "",
        pincode: "",
        country: "",
      },
      address_list: [],
      address_list_demo: [
        {
          name: "Bhavesh Javar",
          title: "",
          address_type: "",
          address_line1: "D-503,Anmol Residency",
          address_line2: "Near Krishna Bunglows,New Ranip",
          city: "AHMEDABAD",
          state: "GUJARAT",
          pincode: "382470",
          country: "India",
          phone_no: "6359985959",
        },
        {
          name: "Bhavesh Javar",
          title: "",
          address_type: "",
          address_line1: "D-503,Anmol Residency",
          address_line2: "Near Krishna Bunglows,New Ranip",
          city: "AHMEDABAD",
          state: "GUJARAT",
          pincode: "382470",
          country: "India",
          phone_no: "6359985959",
        },
        {
          name: "Bhavesh Javar",
          title: "",
          address_type: "",
          address_line1: "D-503,Anmol Residency",
          address_line2: "Near Krishna Bunglows,New Ranip",
          city: "AHMEDABAD",
          state: "GUJARAT",
          pincode: "382470",
          country: "India",
          phone_no: "6359985959",
        },
      ],
      isSkeletonLoaded: true,
    };
  },
  mounted() {
    this.get_customer_information();
    this.get_addresses();
  },
  methods: {
    OpenAddressModal(add_address, address) {
      this.add_address = add_address;
      if (!add_address) {
        (this.add_edit_address.name = address.name),
          (this.add_edit_address.address_title = address.address_title),
          (this.add_edit_address.address_type = address.address_type),
          (this.add_edit_address.address_line1 = address.address_line1),
          (this.add_edit_address.address_line2 = address.address_line2),
          (this.add_edit_address.city = address.city),
          (this.add_edit_address.state = address.state),
          (this.add_edit_address.pincode = address.pincode),
          (this.add_edit_address.country = address.country);
      } else {
        (this.add_edit_address.name = ""),
          (this.add_edit_address.address_title = ""),
          (this.add_edit_address.address_type = ""),
          (this.add_edit_address.address_line1 = ""),
          (this.add_edit_address.address_line2 = ""),
          (this.add_edit_address.city = ""),
          (this.add_edit_address.state = ""),
          (this.add_edit_address.pincode = ""),
          (this.add_edit_address.country = "");
      }
      this.$refs["my-modal"].show();
    },
    CloseAddressModal() {
      this.submit_address();
    },
    async get_customer_information() {
      await CommonApi.get_data(
        "customer_self_service.api.portal.get_customer_information"
      ).then((res) => {
        if (res && res.data) {
          this.customer_information.customer_name = res.data.customer_name;
          this.customer_information.email_id = res.data.email_id;
          this.customer_information.mobile_no = res.data.mobile_no;
          this.customer_information.pan = res.data.pan;
          this.customer_information.website = res.data.website;
          this.customer_primary_address = res.data.customer_primary_address;
        }
      });
    },
    async get_addresses() {
      await CommonApi.get_data(
        "customer_self_service.api.portal.get_addresses"
      ).then((res) => {
        if (res && res.data) {
          // this.customer_information.customer_name = res.data.customer_name;
          this.address_list = res.data;
          this.isSkeletonLoaded = false;
        }
      });
    },
    async update_customer_information() {
      var bodyFormData = new FormData();
      bodyFormData.append("data", JSON.stringify(this.customer_information));
      await CommonApi.post_data(
        "customer_self_service.api.portal.update_customer_information",
        bodyFormData
      ).then((res) => {
        if (res && !res._server_messages) {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
        } else {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
        }
      });
    },
    async submit_address() {
      var bodyFormData = new FormData();
      bodyFormData.append("data", JSON.stringify(this.add_edit_address));
      var address_api_path = "";
      if (this.add_edit_address.name == "")
        address_api_path = "customer_self_service.api.portal.create_address";
      else address_api_path = "customer_self_service.api.portal.update_address";
      await CommonApi.post_data(address_api_path, bodyFormData).then((res) => {
        if (res && !res._server_messages) {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
          this.get_addresses();
          (this.add_edit_address.name = ""),
            (this.add_edit_address.address_title = ""),
            (this.add_edit_address.address_type = ""),
            (this.add_edit_address.address_line1 = ""),
            (this.add_edit_address.address_line2 = ""),
            (this.add_edit_address.city = ""),
            (this.add_edit_address.state = ""),
            (this.add_edit_address.pincode = ""),
            (this.add_edit_address.country = "");
          this.$refs["my-modal"].hide();
        } else {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
        }
      });
    },
    async update_password() {
      var bodyFormData = new FormData();
      bodyFormData.append("data", JSON.stringify(this.password_form));
      await CommonApi.post_data(
        "customer_self_service.api.portal.change_password",
        bodyFormData
      ).then((res) => {
        if (res && !res._server_messages) {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
          this.password_form = {
            current_password: "",
            new_password: "",
          };
        } else {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
        }
      });
    },
    async make_default_address(address) {
      let data = new FormData();
      data = {
        data: JSON.stringify({ customer_primary_address: address }),
      };
      await CommonApi.post_data(
        "customer_self_service.api.portal.update_customer_default_address",
        data
      ).then((res) => {
        if (res && !res._server_messages) {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
          this.get_addresses();
          this.get_customer_information();
        } else {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
        }
      });
    },
    confirm_delete_address(name) {
      this.$bvModal
        .msgBoxConfirm("Are you sure?")
        .then((value) => {
          if (value == true) {
            this.delete_address(name);
          }
        })
        .catch((err) => {
          // An error occurred
          console.log(err);
        });
    },
    delete_address(name) {
      let data = new FormData();
      data = {
        data: JSON.stringify({
          name: name,
        }),
      };
      CommonApi.post_data(
        "customer_self_service.api.portal.delete_address",
        data
      ).then((res) => {
        if (res && !res._server_messages) {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
          this.get_addresses();
        } else {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
        }
      });
    },
  },
};
</script>
<style scoped>
.save-address-modal {
  cursor: pointer;
  background-color: var(--button-color);
  border: 1px solid var(--button-color);
  border-radius: 5px;
  color: #fff;
  width: 100px;
  margin-right: -16px;
}

.save-address-modal:hover {
  color: #fff !important;
  background-color: var(--button-color) !important;
  border-color: var(--button-color) !important;
}

.add-addres-modal .mandatory {
  color: red;
}

.card-title {
  font-size: 1.1rem;
  margin-bottom: 1.5rem;
}

.badge-outline-primary {
  background: unset;
  border: 1px solid var(--active-color);
  color: var(--active-color);
}

.card-link {
  color: var(--active-link-color) !important;
}
</style>
