<template>
  <div class="dashboard new-ticket">
    <BreadCrumb title="New Ticket" />
    <div>
      <b-card-group deck>
        <b-card>
          <div class="new-ticket-form">
            <form>
              <div class="ticket-form">
                <!-- Subject Start -->
                <div class="col form-group mb-3 mt-2">
                  <label class="mb-2" for="Subject">Subject</label>
                  <input
                    type="text"
                    class="form-control"
                    name="Subject"
                    placeholder="Subject"
                    required
                    v-model="subject"
                  />
                </div>
                <!-- Subject End -->

                <!-- Description Start -->
                <div class="col form-group mb-3">
                  <label class="mb-2" for="Description">Description</label>
                  <ckeditor :editor="editor" v-model="description"></ckeditor>
                </div>
                <!-- Description End -->

                <!-- Attachment Start -->
                <!-- <div class="col form-group mb-3" v-if="attachment_file.length">
                  <div class="attachment-files">
                    <div v-for="(item, index) in attachment_file" :key="index">
                      <div class="Stock">
                        {{ index + 1 }}.
                        <label class="dialog_label">
                          {{ item.file_name }}
                        </label>
                        <span class="close-button" @click="remove_item(index)"
                          ><i class="fa fa-times"
                        /></span>
                      </div>
                    </div>
                  </div>
                </div>

                <div class="upload-btn-wrapper">
                  <button type="button" class="btn attachment-button">
                    + Attachment
                  </button>
                  <input type="file" name="myfile" @change="onFileChange" />
                </div> -->
                <!-- Attachment End -->

                <!-- Save Start -->
                <div class="col form-group mb-3 d-flex justify-content-end">
                  <button
                    type="button"
                    class="btn Save-button"
                    :disabled="subject === '' || description === ''"
                    @click="new_support_ticket()"
                  >
                    Save
                  </button>
                </div>
                <!-- Save End -->
              </div>
            </form>
          </div>
        </b-card>
      </b-card-group>
    </div>
  </div>
</template>
        
<script>
import CKEditor from "@ckeditor/ckeditor5-vue";
import ClassicEditor from "@ckeditor/ckeditor5-build-classic";
import CommonApi from "../../services/CommonApi";
import BreadCrumb from "../../components/breadcrumbs.vue";

export default {
  name: "New-Ticket",
  components: { ckeditor: CKEditor.component, BreadCrumb },
  data() {
    return {
      editor: ClassicEditor,
      subject: "",
      description: "",
      attachment_file: [],
    };
  },
  methods: {
    onFileChange(e) {
      if (this.attachment_file.length < 5) {
        var files = e.target.files;
        if (!files.length) return;
        this.createImage(files[0]);
      } else {
        this.$toasted.show("Maximum 5 Files are Allowed", {
          theme: "toasted-primary",
          position: "bottom-right",
          duration: 1000,
        });
      }
    },
    createImage(file) {
      var reader = new FileReader();
      reader.onload = (e) => {
        this.attachment_file.push({
          file_name: file.name,
          file_result: e.target.result,
        });
      };
      reader.readAsDataURL(file);
    },
    remove_item(id) {
      this.attachment_file.splice(id, 1);
    },
    /*** Create New Ticket ***/
    async new_support_ticket() {
      let param = { subject: this.subject, description: this.description };
      var bodyFormData = new FormData();
      bodyFormData.append("data", JSON.stringify(param));
      await CommonApi.post_data(
        "customer_self_service.api.portal.new_support_ticket",
        bodyFormData
      ).then((res) => {
        if (res && res.data) {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
          this.$router.push("support-tickets");
        }
      });
    },
  },
};
</script>
<style scoped>
.ticket-form {
  float: left;
  width: 70%;
  padding: 0 0px;
}
.dialog_label {
  display: inline;
}
</style>