<template>
  <div class="dashboard support-ticket">
    <BreadCrumb title="Support Ticket" :is_support_ticket="true" />
    <div v-if="isSkeletonLoaded">
      <Skeleton />
    </div>
    <div v-if="!isSkeletonLoaded">
      <b-card-group deck>
        <b-card>
          <div>
            <b-table
              responsive
              :items="support_ticket_list_items"
              :fields="support_ticket_list_fields"
            >
              <template #cell(#)="data">
                {{ data.index + 1 }}
              </template>

              <template #cell(View)="data">
                <img
                  class="remark-icon"
                  src="../../assets/Icons/Dashboard/remarks.svg"
                  @click="navigateUrl('view-ticket/' + data.item.name)"
                />
              </template>
            </b-table>

            <div class="no-data" v-if="!support_ticket_list_items.length">
              No data found
            </div>
          </div>
        </b-card>
      </b-card-group>
    </div>
  </div>
</template>
        
<script>
import CommonApi from "../../services/CommonApi";
import BreadCrumb from "../../components/breadcrumbs.vue";
import Skeleton from "./supportTicket_skeleton.vue";

export default {
  name: "Support-Tickets",
  components: {
    BreadCrumb,
    Skeleton,
  },
  data() {
    return {
      support_ticket_list_fields: [
        "name",
        "subject",
        "status",
        "opening_date",
        "View",
      ],
      support_ticket_list_items: [],
      isSkeletonLoaded: true,
    };
  },
  methods: {
    /*** Navigate to Path ***/
    navigateUrl(url) {
      this.$router.push(url);
    },
    /*** Get All Ticket lists ***/
    async get_support_tickets() {
      await CommonApi.get_data(
        "customer_self_service.api.portal.get_support_tickets"
      ).then((res) => {
        if (res) {
          this.isSkeletonLoaded = false
          this.support_ticket_list_items = res.data;
        }
      });
    },
  },
  mounted() {
    this.get_support_tickets();
  },
};
</script>