<template>
  <div class="dashboard new-quotation">
    <BreadCrumb title="Request Quotation" />
    <div class="row quotation-top cart" v-if="quotation_data.length">
      <div class="col-md-8">
        <div class="row">
          <div
            class="card ml-3 mb-3"
            style="width: 15rem"
            v-for="item in quotation_data"
            v-bind:key="item.id"
          >
            <img
              class="card-img-top"
              style="height: 200px"
              v-bind:src="config.base_url_for_Image + item.image"
              alt="Quotation Image"
            />
            <div class="card-body">
              <h5 class="card-title category-heading">{{ item.item_name }}</h5>
              <div class="d-flex">
                <p class="card-text mt-2">Qty</p>
                <div class="quantity_class mt-1">
                  <div class="wrapper">
                    <button
                      class="qtybtn btn--minus"
                      @click="changeCounter(item, 'subtract', false)"
                      type="button"
                      name="button"
                    >
                      -
                    </button>
                    <input
                      class="quantity"
                      disabled
                      type="text"
                      name="name"
                      :value="item.qty"
                    />
                    <button
                      class="qtybtn btn--plus"
                      @click="changeCounter(item, 'add', false)"
                      type="button"
                      name="button"
                    >
                      +
                    </button>
                  </div>
                </div>
                <div>
                  <button @click="add_item(item)" class="btn add-button ml-3">
                    Add
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="col-md-4">
        <div class="card">
          <div class="card-body">
            <h4 class="card-title">Cart</h4>
            <div
              class="d-flex justify-content-between"
              v-if="selected_items.length"
            >
              <p class="summary-heading">Item Name</p>
              <p class="summary-heading qty-title m-0">Qty</p>
            </div>
            <div class="ul-cart__order" v-if="selected_items.length">
              <div
                class="d-flex justify-content-between"
                v-for="item in selected_items"
                v-bind:key="item.id"
              >
                <p class="bold">{{ item.item_name }} :</p>
                <!-- <p class="text-16 m-0">{{ item.qty }}</p> -->
                <div class="quantity_class">
                  <div class="wrapper">
                    <button
                      class="qtybtn btn--minus"
                      @click="changeCounter(item, 'subtract', true)"
                      type="button"
                      name="button"
                    >
                      -
                    </button>
                    <input
                      class="quantity"
                      disabled
                      type="text"
                      name="name"
                      :value="item.qty"
                    />
                    <button
                      class="qtybtn btn--plus"
                      @click="changeCounter(item, 'add', true)"
                      type="button"
                      name="button"
                    >
                      +
                    </button>
                  </div>
                </div>
              </div>
              <div class="text-center">
                <button
                  class="btn submit-button ml-3"
                  :disabled="disabled"
                  @click="new_quotation_request()"
                >
                  Continue
                </button>
              </div>
            </div>
          </div>
          <div
            class="summary-heading mb-3 text-center"
            v-if="!selected_items.length"
          >
            Add items to Proceed
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
        
<script>
import BreadCrumb from "../components/breadcrumbs.vue";
import config from "../services/CommonApi";
import CommonApi from "../services/CommonApi";

export default {
  name: "Request-Quotation",
  components: {
    BreadCrumb,
  },
  data() {
    return {
      quotation_data: [],
      selected_items: [],
      config: config,
      disabled: false,
    };
  },
  methods: {
    /*** Inc / Dec Quantity ***/
    changeCounter(original_item, type, isSummary) {
      if (isSummary) {
        if (original_item.qty === 1 && type === "subtract") {
          const index = this.selected_items.findIndex(
            (object) => object.id === original_item.id
          );
          this.selected_items.splice(index, 1);
        }
        this.selected_items.filter(function (item) {
          if (item.id === original_item.id) {
            if (type === "add") {
              item.qty = item.qty + 1;
            } else if (type === "subtract") {
              item.qty = item.qty - 1;
            }
          }
        });
        var summary = {
          summary: this.selected_items,
        };
        localStorage.setItem("summary", JSON.stringify(summary));
      } else {
        this.quotation_data.filter(function (item) {
          if (item.id === original_item.id) {
            if (type === "add") {
              item.qty = item.qty + 1;
            } else if (type === "subtract" && item.qty > 1) {
              item.qty = item.qty - 1;
            }
          }
        });
      }
    },
    /*** Add item to checkout ***/
    add_item(original_item) {
      const index = this.selected_items.findIndex(
        (object) => object.id === original_item.id
      );
      let qty_added = true;
      if (this.selected_items.length && index !== -1) {
        if (
          this.selected_items[index].qty <
          this.selected_items[index].qty + original_item.qty
        ) {
          qty_added = true;
        } else if (
          this.selected_items[index].qty >
          this.selected_items[index].qty + original_item.qty
        ) {
          qty_added = false;
        }
      }

      if (index === -1) {
        this.selected_items.push({
          id: original_item.id,
          item_name: original_item.item_name,
          qty: original_item.qty,
        });
      } else {
        this.selected_items[index].qty =
          this.selected_items[index].qty + original_item.qty;
      }
      if (qty_added) {
        this.$toasted.show(original_item.item_name + " added !", {
          theme: "toasted-primary",
          position: "bottom-right",
          duration: 1000,
        });
      }
      this.reset_quantity();
    },
    /*** Get All Quotation lists ***/
    async get_item_list() {
      await CommonApi.get_data(
        "customer_self_service.api.portal.get_item_list"
      ).then((res) => {
        if (res && res.data.length) {
          this.quotation_data = [];
          res.data.map((item) => {
            this.quotation_data.push({
              id: item.item_code,
              item_name: item.item_name,
              qty: 1,
              image: item.image,
            });
          });
        }
      });
    },
    /*** Submit New Quotation ***/
    async new_quotation_request() {
      this.disabled = true;
      let data = [];
      this.selected_items.map((item) => {
        data.push({ item: item.id, qty: item.qty });
      });
      let param = { items: data };
      var bodyFormData = new FormData();
      bodyFormData.append("data", JSON.stringify(param));
      await CommonApi.post_data(
        "customer_self_service.api.portal.new_quotation_request",
        bodyFormData
      ).then((res) => {
        if (res) {
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
          this.reset_data();
        }
      });
    },
    reset_data() {
      this.get_item_list();
      this.selected_items = [];
      this.disabled = false;
      localStorage.removeItem("summary");
    },
    reset_quantity() {
      this.quotation_data.forEach((data) => {
        data.qty = 1;
      });
      var summary = {
        summary: this.selected_items,
      };
      localStorage.setItem("summary", JSON.stringify(summary));
    },
    check_existying_summary() {
      this.selected_items = localStorage.getItem("summary")
        ? JSON.parse(localStorage.getItem("summary")).summary
        : [];
    },
  },
  mounted() {
    this.get_item_list();
    this.check_existying_summary();
  },
};
</script>
<style scoped>
.quotation-top {
  margin-top: -10px;
}
</style>