<template>
  <div>
    <div v-if="isSkeletonLoaded">
      <Skeleton />
    </div>
    <div
      class="dashboard view-ticket"
      v-if="ticket_data.comments && !isSkeletonLoaded"
    >
      <div>
        <b-card-group deck>
          <b-card
            :title="ticket_data.subject"
            header-tag="header"
            footer-tag="footer"
          >
            <template #header>
              <div class="d-flex justify-content-between">
                <p class="m-0">
                  #{{ ticket_id }}
                  <template v-if="ticket_data.status !== 'Open'">
                    - Closed</template
                  >
                </p>
                <p class="m-0">Date : {{ ticket_data.opening_date }}</p>
              </div>
            </template>
            <b-card-text>
              <p v-html="ticket_data.description"></p>
              <hr>
            </b-card-text>
            <b-card-body>
              <section>
                <div class="container-fluid chat-container">
                  <div class="row">
                    <div class="col">
                      <ul class="list-unstyled">
                        <li
                          v-for="(item, index) in ticket_data.comments"
                          :key="index"
                          class="d-flex justify-content-between mb-2"
                        >
                          <div  >
                          <b-avatar
                            v-if="item.name == 'Administrator'"
                            text="A"
                            variant="dark"
                          ></b-avatar>
                          </div>
                          <div style="width:95%">
                            <div class="card chat_card" 
                            :style="item.name == 'Administrator' ? 'float:left;' : 'float:right;'"
                            >
                              <div class="card-body p-2">
                                <p v-if="item.name == 'Administrator'" class="fw-bold mb-0">{{ item.name }}
                                  <span class="text-muted small mb-0">{{ item.date }} </span>
                                </p>
                                <p v-else class="fw-bold mb-0">You <span class="text-muted small mb-0">{{ item.date }} </span></p>
                                
                                <p class="mb-0" v-html="item.comment"></p>
                              </div>
                            </div>
                          </div>
                          <div  >
                          <b-avatar
                          v-if="item.name !== 'Administrator'" 
                            variant="dark"
                          ></b-avatar>
                          </div>
                        </li>
                      </ul>
                    </div>
                  </div>
                </div>
              </section>
            </b-card-body>
            <template #footer>
              <div class="">
                <div class="card text-dark ckeditor">
                  <ckeditor :editor="editor" v-model="comment"></ckeditor>
                </div>
              </div>
              <!-- Save Start -->
              <div
                class="
                  col-md-12 col-lg-12
                  form-group
                  mb-3
                  d-flex
                  justify-content-end
                "
              >
                <button
                  type="button"
                  class="btn Save-button"
                  :disabled="comment === ''"
                  @click="add_comment()"
                >
                  Save
                </button>
              </div>
            </template>
          </b-card>
        </b-card-group>
      </div>
    </div>
  </div>
</template>
        
<script>
import CKEditor from "@ckeditor/ckeditor5-vue";
import ClassicEditor from "@ckeditor/ckeditor5-build-classic";
import CommonApi from "../../services/CommonApi";
import Skeleton from "./editTicket_skeleton.vue";

export default {
  name: "View-Ticket",
  components: { ckeditor: CKEditor.component, Skeleton },
  data() {
    return {
      comment: "",
      editor: ClassicEditor,
      ticket_data: [],
      ticket_id: this.$route.params.ticket_id,
      isSkeletonLoaded: true,
    };
  },
  methods: {
    /*** Get Ticket details ***/
    async get_support_ticket_detail() {
      let param = { ticket: this.ticket_id };
      param = new URLSearchParams(param);
      await CommonApi.get_data(
        "customer_self_service.api.portal.get_support_ticket_detiail",
        param
      ).then((res) => {
        if (res && res.data) {
          this.isSkeletonLoaded = false;
          this.ticket_data = res.data;
        } else {
          this.$toasted.show(res, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
          this.$router.push({ path: "/support-ticket" });
        }
      });
    },
    /*** Add New Comments ***/
    async add_comment() {
      let param = { ticket: this.ticket_id, comment: this.comment };
      var bodyFormData = new FormData();
      bodyFormData.append("data", JSON.stringify(param));
      await CommonApi.post_data(
        "customer_self_service.api.portal.add_comment",
        bodyFormData
      ).then((res) => {
        if (res && res.data) {
          this.comment = "";
          this.get_support_ticket_detail();
          this.$toasted.show(res.message, {
            theme: "toasted-primary",
            position: "bottom-right",
            duration: 1000,
          });
        }
      });
    },
  },
  mounted() {
    this.get_support_ticket_detail();
  },
};
</script>
<style >
/* .ckeditor {
  border: none !important;
} */
/* .justify-content-between {
  justify-content: space-between !important;
} */
.chat_card{
  min-width: 300px !important;
  max-width: 70%;
}
.ql-editor.read-mode p, .card-body p{
  margin: 0 !important;
}
.chat-container{
  font-size: 13px;
}
</style>
