  <div class="dashboard place-order">
    <BreadCrumb title="Place Order" :is_place_order="true" />
    <div v-if="isSkeletonLoaded">
      <Skeleton />
    </div>
    <div v-if="!isSkeletonLoaded">
      <div class="row" v-if="categories_list.length">
        <div class="col-8 categories-list cart" v-if="!showItemList">
          <div class="row">
            <div
              class="column"
              v-for="item in categories_list"
              v-bind:key="item.id"
              @click="showItem(item)"
            >
              <div class="card ml-3 mb-3">
                <img
                  class="card-img-top"
                  style="height: 200px"
                  v-bind:src="config.base_url_for_Image + item.image"
                  alt="Quotation Image"
                  v-if="item.image"
                />
                <b-skeleton-img
                  animation
                  height="200px"
                  v-if="!item.image"
                ></b-skeleton-img>
                <div class="card-body">
                  <h5 class="card-title category-heading">
                    {{ item.name }}
                  </h5>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div class="col-8 item-list cart" v-if="showItemList">
          <div class="row">
            <div class="sms-details-back link">
              <div class="sms-details-back-image back-arrow">
                <button class="btn back-button mr-3" @click="hideItem()">
                  <i aria-hidden="true" class="fa fa-angle-left"></i
                  ><span class="back"> Back</span>
                </button>
                <span class="category">{{ selected_category }}</span>
              </div>
            </div>
            <div
              class="column"
              v-for="item in item_list[0]"
              v-bind:key="item.id"
            >
              <div class="card ml-3 mb-3">
                <img
                  class="card-img-top"
                  style="height: 200px"
                  v-bind:src="config.base_url_for_Image + item.image"
                  alt="Quotation Image"
                  v-if="item.image"
                />
                <b-skeleton-img
                  animation
                  height="200px"
                  v-if="!item.image"
                ></b-skeleton-img>
                <div class="card-body">
                  <h5 class="card-title category-heading">
                    {{ item.item_name }}
                  </h5>
                  <div class="d-flex">
                    <p class="card-text mt-2">Qty</p>
                    <div class="quantity_class mt-1">
                      <div class="wrapper">
                        <button
                          class="qtybtn btn--minus"
                          @click="changeCounter(item, 'subtract')"
                          type="button"
                          name="button"
                        >
                          -
                        </button>
                        <input
                          class="quantity"
                          disabled
                          type="text"
                          name="name"
                          :value="item.qty"
                        />
                        <button
                          class="qtybtn btn--plus"
                          @click="changeCounter(item, 'add')"
                          type="button"
                          name="button"
                        >
                          +
                        </button>
                      </div>
                    </div>
                    <div>
                      <button @click="add_item(item)" class="btn add-button">
                        Add
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div
          class="col-4 cart"
          :class="{
            'show-list': showItemList,
          }"
        >
          <Cart />
        </div>
      </div>
    </div>
  </div>
