  },
  methods: {
    /*** Show Category Items ***/
    showItem(id) {
      this.showItemList = true;
      this.selected_category = id.item_name;
      this.item_list = this.categories_list
        .filter((data) => data.name === id.name)
        .map((data) => data.items);
    },
    /*** Hide Category Items ***/
    hideItem() {
      this.showItemList = false;
    },
    /*** Inc / Dec Quantity ***/
    changeCounter(original_item, type) {
      this.categories_list.filter(function (item) {
        item.items.filter((data) => {
          if (data.item_code === original_item.item_code) {
            if (type === "add") {
              data.qty = parseInt(data.qty) + 1;
            } else if (type === "subtract" && data.qty > 1) {
              data.qty = parseInt(data.qty) - 1;
            }
          }
        });
      });
    },
    /*** Add item to checkout ***/
    add_item(original_item) {
      this.$store.dispatch("cart/addCart", original_item);
      this.$toasted.show(original_item.item_name + " added !", {
        theme: "toasted-primary",
        position: "bottom-right",
        duration: 1000,
      });

      this.reset_quantity();
    },
    /*** Reset Qty after adding to cart ***/
    reset_quantity() {
      this.categories_list.forEach(function (item) {
        item.items.forEach((data) => {
          data.qty = 1;
        });
      });
    },
    async get_place_order_items() {
      await CommonApi.get_data(
        "customer_self_service.api.portal.get_place_order_items"
      ).then((res) => {
        this.categories_list = [];
        this.isSkeletonLoaded = false;
        if (res && res.data.length) {
          this.categories_list = res.data;
        }
      });
    },
  },
  mounted() {
    this.get_place_order_items();
  },
};
