<template>
  <div class="card">
    <div class="card-body">
      <h4 class="card-title">Cart</h4>
      <div class="d-flex justify-content-between" v-if="cartData.length">
        <p class="summary-heading">Item Name</p>
        <p class="summary-heading qty-title m-0">Qty</p>
      </div>
      <div class="ul-cart__order" v-if="cartData.length">
        <div
          class="d-flex justify-content-between"
          v-for="item in cartData"
          v-bind:key="item.id"
        >
          <p class="bold">{{ item.item_name }} :</p>
          <div class="quantity_class">
            <div class="wrapper">
              <button
                class="qtybtn btn--minus"
                @click="changeCounter(item, 'subtract')"
                type="button"
                name="button"
              >
                -
              </button>
              <input
                class="quantity"
                disabled
                type="text"
                name="name"
                :value="item.qty"
              />
              <button
                class="qtybtn btn--plus"
                @click="changeCounter(item, 'add')"
                type="button"
                name="button"
              >
                +
              </button>
            </div>
          </div>
        </div>
        <div class="text-center">
          <button
            class="btn submit-button ml-3"
            :disabled="!cartData.length"
            v-if="currentPath == 'place-order'"
            @click="navigateToCheckoutAdd('/checkout-address')"
          >
            Continue
          </button>
          <button
            class="btn submit-button ml-3"
            :disabled="
              !cartData.length || Object.keys(selected_address).length === 0
            "
            v-if="currentPath == 'checkout-address'"
          >
            Place Order
          </button>
        </div>
      </div>
    </div>
    <div class="summary-heading mb-3 text-center" v-if="!cartData.length">
      Add items to Proceed
    </div>
  </div>
</template>

<script>
export default {
  name: "Cart-Page",
  props: {
    selected_address: {
      default: "",
    },
  },
  data() {
    return {
      cartData: [],
    };
  },
  mounted() {
    this.cartData = this.$store.state.cart.cart;
  },
  computed: {
    currentPath() {
      return this.$route.name;
    },
  },
  methods: {
    /*** Inc / Dec Quantity ***/
    changeCounter(original_item, type) {
      if (type === "add") {
        this.$store.dispatch("cart/addQty", original_item);
      } else if (type === "subtract") {
        this.$store.dispatch("cart/removeQty", original_item);
      }
    },
    navigateToCheckoutAdd(url) {
      this.$router.push(url);
    },
  },
  watch: {
    "$store.state.cart.cart": function () {
      this.cartData = this.$store.state.cart.cart;
    },
  },
};
</script>

        
