import axios from "axios";
var base_url = ""
var base_url_for_Image = ""
if(window.location.origin == "http://localhost:8080") {
  // base_url= "https://innovation-sa.nesscale.com/api/method/"
  // base_url_for_Image="https://innovation-sa.nesscale.com"
  base_url= "https://demov14.nesscale.com/api/method/",
  base_url_for_Image="https://demov14.nesscale.com"
}else{
  // base_url = window.location.protocol + window.location.host + "/api/method/"
  // base_url_for_Image = window.location.protocol + window.location.host + "/"
  base_url = window.location.origin + "/api/method/"
  base_url_for_Image = window.location.origin + "/"
}

export default {
  // base_url: "https://demov14.nesscale.com/api/method/",
  // base_url_for_Image:"https://demov14.nesscale.com",
  base_url:base_url,
  base_url_for_Image:base_url_for_Image,
  api_key: "",
  api_secret: "",

  /* Get API Call */
  get_data(url, params = "") {
    this.validate_key();
    let requestOptions = {
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
    };

    if (this.api_key !== null || this.api_secret !== null) {
      requestOptions.headers["Authorization"] =
        "token " + this.api_key + ":" + this.api_secret;
    }

    return axios
      .get(this.base_url + url + "?" + params, requestOptions)
      .then((response) => {
        if (response.status == 200) {
          return response.data;
        } else {
          return alert(response.data.message);
        }
      })
      .catch((error) => {
        if (error.response.status == "403") {
          this.unauthorize_login();
        } else {
          return error.response.data.message;
        }
      });
  },

  /* Post API Call */
  post_data(url, params = "", guest_call = false) {
    let requestOptions = "";
    requestOptions = {
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
    };
    if (!guest_call) {
      this.validate_key();
      requestOptions.headers["Authorization"] =
        "token " + this.api_key + ":" + this.api_secret;
    }
    return axios
      .post(this.base_url + url, params, requestOptions)
      .then((response) => {
        if (response.status == 200) {
          return response.data;
        } else {
          return alert(response.data.message);
        }
      })
      .catch((error) => {
        // if (error.response) {
        //   return error.response.data.message;
        // }
        if (error.response.status == "500") {
          return error.response.data;
        } else {
          return error.response.data.message;
        }
      });
  },

  /* Get Token */
  validate_key() {
    this.api_key = localStorage.getItem("userInfo")
      ? JSON.parse(localStorage.getItem("userInfo")).api_key
      : null;
    this.api_secret = localStorage.getItem("userInfo")
      ? JSON.parse(localStorage.getItem("userInfo")).api_secret
      : null;

    if (this.api_secret == "" || this.api_key == "") {
      this.unauthorize_login();
    }
  },

  /* Remove Token */
  unauthorize_login() {
    localStorage.removeItem("userInfo");
    location.reload();
  },
};
