<template>
  <nav id="sidebar"  :class="!activesidebar ? 'active ' : 'shadow'">
    <div class="sidebar-header">
      <router-link to="/dashboard">
        <img src="../../assets/Icons/Logo/Logo.png" />
        <span class="logo_span">NESSCALE</span>
      </router-link>
    </div>

    <ul class="list-unstyled components">
      <li :class="currentPath == 'Dashboard' ? 'active' : ''">
        <router-link to="/dashboard">
          <b-icon-bar-chart-line
            class="side-menu-image"
          ></b-icon-bar-chart-line>
          <span class="">Dashboard</span></router-link
        >
      </li>

      <li :class="currentPath == 'sales-invoice' ? 'active' : ''">
        <router-link to="/sales-invoice">
          <b-icon-receipt class="side-menu-image"></b-icon-receipt>
          <span>Sales Invoice</span></router-link
        >
      </li>

      <li
        :class="currentPath == 'place-order' ? 'active' : ''"
        v-if="enable_ecommerce == 1"
      >
        <router-link to="/place-order">
          <b-icon-shop-window class="side-menu-image"></b-icon-shop-window>
          <span>Place Order</span></router-link
        >
      </li>
      <li :class="currentPath == 'transactions' ? 'active' : ''">
        <router-link to="/transactions">
          <b-icon-wallet class="side-menu-image"></b-icon-wallet>
          <span>Transactions</span></router-link
        >
      </li>
      <li
        :class="
          currentPath == 'support-tickets' ||
          currentPath == 'new-ticket' ||
          currentPath == 'view-ticket'
            ? 'active'
            : ''
        "
      >
        <router-link to="/support-tickets">
          <b-icon-headset class="side-menu-image"></b-icon-headset>
          <span>Support Tickets</span></router-link
        >
      </li>
    </ul>

    <div class="logo-title">
      <hr style="border-color: #0a0a0a" />
      <ul class="list-unstyled components">
        <p>Nesscale Solutions Private Limited</p>
        <li>
          <a @click="logout()" class="cursor">
            <b-icon-arrow-bar-left
              variant="dark"
              class="side-menu-image"
            ></b-icon-arrow-bar-left>
            <span>Log Out</span></a
          >
        </li>
      </ul>
    </div>
  </nav>
</template>


<script>
import { mapState } from "vuex";
import CommonApi from "@/services/CommonApi";

export default {
  name: "SidebarPage",
  data() {
    return {
      enable_ecommerce: 0,
    };
  },
  computed: {
    ...mapState({
      activesidebar: (state) => state.common.activesidebar,
    }),
    currentPath() {
      return this.$route.name;
    },
  },
  mounted() {
    this.$store.state.common.activesidebar = true;
    this.validate();
  },
  methods: {
    logout() {
      localStorage.removeItem("userInfo");
      this.$router.push("/auth/login").catch((error) => {
        console.info(error.message);
      });
    },
    async validate() {
      await CommonApi.get_data(
        "customer_self_service.api.portal.validate_ecommerce"
      ).then((res) => {
        this.enable_ecommerce = res.message;
      });
    },
  },
};
</script>

<style scoped>
.logo_span {
  line-height: 34px;
  font-size: 26px;
  vertical-align: top;
  margin-left: 10px;
  font-weight: bold;
}
</style>