<template>
  <div class="dashboard invoice-history">
    <BreadCrumb title="Invoice History" />
    <div v-if="isSkeletonLoaded">
      <Skeleton />
    </div>
    <div v-if="!isSkeletonLoaded">
      <b-card-group deck>
        <b-card>
          <div>
            <b-table
              responsive
              :items="invoice_history_items"
              :fields="invoice_history_fields"
            >
              <template #cell(#)="data">
                {{ data.index + 1 }}
              </template>

              <template #cell(name)="data">
                {{ data.value }}
              </template>

              <template #cell(posting_date)="data">
                {{ data.value }}
              </template>

              <template #cell(due_date)="data">
                {{ data.value }}
              </template>

              <template #cell(grand_total)="data">
                {{ data.value }}
              </template>

              <template #cell(status)="data">
                {{ data.value }}
              </template>

              <template #cell(Download)="data">
                <img
                  class="download-icon"
                  @click="downloadPDF(data.item.name)"
                  src="../../assets/Icons/Dashboard/Download.svg"
                />
              </template>
            </b-table>

            <!-- <b-modal ref="my-modal" centered hide-footer>
              <template #modal-title>
                <b>Remarks</b>
                <div class="row d-flex remark-modal">
                  <div class="col">
                    <p>Invoice ID : {{ remarks_modal.name }}</p>
                  </div>
                  <div style="margin-left: 25px">
                    <p>Invoice Date : {{ remarks_modal.posting_date }}</p>
                  </div>
                </div>
              </template>
              <div class="remark-modal">
                <h5>
                  {{ remarks_modal.remarks }}
                </h5>
              </div>
              <b-button class="mt-3 close-modal" @click="CloseRemarkModal()"
                >Close</b-button
              >
            </b-modal> -->

            <div class="no-data" v-if="!invoice_history_items.length">
              No data found
            </div>
          </div>
        </b-card>
      </b-card-group>
    </div>
  </div>
</template>
        
<script>
import CommonApi from "@/services/CommonApi";
import axios from "axios";
import BreadCrumb from "../../components/breadcrumbs.vue";
import Skeleton from "./salesInvoice_skeleton.vue";

export default {
  name: "SalesInvoice",
  components: {
    BreadCrumb,
    Skeleton,
  },
  data() {
    return {
      invoice_history_fields: [
        "#",
        { key: "name", label: "Invoice Id" },
        { key: "posting_date", label: "Invoice Date" },
        { key: "due_date", label: "Due Date" },
        { key: "grand_total", label: "Amount" },
        { key: "status", label: "Status" },
        "Download",
      ],
      invoice_history_items: [],
      remarks_modal: {
        name: "",
        posting_date: "",
        remarks: "",
      },
      isSkeletonLoaded: true,
    };
  },
  methods: {
    // OpenRemarkModal(data) {
    //   this.remarks_modal.name = data.name;
    //   this.remarks_modal.posting_date = data.posting_date;
    //   this.remarks_modal.remarks = data.remarks;
    //   this.$refs["my-modal"].show();
    // },
    // CloseRemarkModal() {
    //   this.$refs["my-modal"].hide();
    //   this.remarks_modal.name = "";
    //   this.remarks_modal.posting_date = "";
    //   this.remarks_modal.remarks = "";
    // },
    /* Get Invoice Details API */
    async get_invoice_details() {
      await CommonApi.get_data(
        "customer_self_service.api.portal.get_invoice_details"
      ).then((res) => {
        if (res) {
          this.isSkeletonLoaded = false
          this.invoice_history_items = res.data;
        }
      });
    },

    /* Get Invoice Attachment API */
    downloadPDF(id) {
      this.$toasted.show("Dowloading Invoice...", {
        theme: "toasted-primary",
        position: "bottom-right",
        duration: 1000,
      });
      let param = { invoice_id: id };
      param = new URLSearchParams(param);
      axios.defaults.headers.common["Authorization"] =
        "token " + CommonApi.api_key + ":" + CommonApi.api_secret;
      axios({
        url:
          CommonApi.base_url +
          "customer_self_service.api.portal.get_invoice_attachment?" +
          param,
        method: "GET",
        responseType: "blob", // <= important
      }).then((response) => {
        const url = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement("a");
        link.href = url;
        link.setAttribute("download", "invoice.pdf");
        document.body.appendChild(link);
        link.click();
      });
    },
  },
  mounted() {
    this.get_invoice_details();
  },
};
</script>
<style scoped>
.remark-modal > div > p,
.remark-modal > h5 {
  font-size: 15px;
  color: #717782;
}

.close-modal {
  cursor: pointer;
  background-color: #fff;
  border: 1px solid #f54d4d;
  border-radius: 5px;
  color: #f54d4d;
  width: 163px;
  margin-left: 143px;
}
.close-modal:hover {
  color: #f54d4d !important;
  background-color: #fff !important;
  border-color: #f54d4d !important;
}
</style>