<template>
  <div class="dashboard transaction-history">
    <BreadCrumb title="Transactions" v-if="!isSkeletonLoaded" />
    <div v-if="isSkeletonLoaded">
      <Skeleton />
    </div>
    <div v-if="!isSkeletonLoaded">
      <div class="notification">
        <div class="row">
          <!-- <div class="col-12 mb-3 col-sm-6 col-lg-2 mb-lg-0">
          <div class="invoice-actions">
            <input
              type="search"
              placeholder="Search..."
              class="form-control form-control-sm"
            />
          </div>
        </div> -->
          <div class="mb-3 mb-lg-0 mr-3 adjust-input">
            <DatePicker
              lang="en"
              v-model="startdate"
              placeholder="Select Start Date"
              input-class="form-control input-no-border bg-gray-lighter"
            >
            </DatePicker>
          </div>
          <div class="mb-3 mb-lg-0 adjust-input">
            <DatePicker
              lang="en"
              v-model="enddate"
              placeholder="Select End Date"
              input-class="form-control input-no-border bg-gray-lighter"
            >
            </DatePicker>
          </div>
          <button
            class="btn search-button adjust-input"
            :disabled="startdate === null || enddate === null"
            @click="get_ledger('false')"
          >
            Submit
          </button>
          <button
            class="btn search-button adjust-input"
            :disabled="
              startdate === null ||
              enddate === null ||
              !payment_history_items.length
            "
            @click="get_ledger('True')"
          >
            Download
          </button>
        </div>
      </div>
      <div class="mt-3">
        <b-card-group deck>
          <b-card>
            <!-- <div class="row d-flex account-details" style="width: 20%">
            <div class="col first-acc-details">
              <h4>Balance</h4>
              <h4>$12,471.25</h4>
            </div>
          </div>
          <hr /> -->
            <div>
              <b-table
                responsive
                :items="payment_history_items"
                :fields="payment_history_fields"
              >
                <!-- <template #cell(ViewPayment)>
                <img
                  class="remark-icon"
                  src="../assets/Icons/Dashboard/remarks.svg"
                />
              </template> -->

                <template #cell(Ref)="data">
                  {{ data.value.voucher_type }}
                  <br />
                  {{ data.value.voucher_no }}
                </template>

                <template #cell(Remarks)="data">
                  Against: {{ data.value.Against }}
                  <br />
                  Remarks: {{ data.value.Remarks }}
                </template>
              </b-table>

              <div class="no-data" v-if="!payment_history_items.length">
                No data found
              </div>
            </div>
          </b-card>
        </b-card-group>
      </div>
    </div>
  </div>
</template>
        
<script>
import BreadCrumb from "../../components/breadcrumbs.vue";
import DatePicker from "vue2-datepicker";
import CommonApi from "@/services/CommonApi";
import axios from "axios";
import Skeleton from "./transactions_skeleton.vue";

export default {
  name: "TransactionHistory",
  components: {
    BreadCrumb,
    DatePicker,
    Skeleton,
  },
  data() {
    return {
      payment_history_fields: [
        "Date",
        { key: "Ref", label: "Ref" },
        { key: "Remarks", label: "Remarks" },
        "Debit",
        "Credit",
        "Balance(Dr-Cr)",
      ],
      payment_history_items: [],
      startdate: "",
      enddate: "",
      isSkeletonLoaded: true,
    };
  },
  methods: {
    convert(str) {
      var date = new Date(str),
        mnth = ("0" + (date.getMonth() + 1)).slice(-2),
        day = ("0" + date.getDate()).slice(-2);
      return [date.getFullYear(), mnth, day].join("-");
    },
    /* Get ledger Details API */
    async get_ledger(isDownload) {
      var data = new FormData();
      data.append("from_date", this.convert(this.startdate));
      data.append("to_date", this.convert(this.enddate));
      data.append("download", isDownload);

      if (isDownload === "false") {
        await CommonApi.post_data(
          "customer_self_service.api.portal.get_ledger",
          data
        ).then((res) => {
          this.payment_history_items = [];
          this.isSkeletonLoaded = false
          if (res && res.data.data.length) {
            res.data.data.map((data) => {
              this.payment_history_items.push({
                Date: data.posting_date,
                Ref: {
                  voucher_type: data.voucher_type,
                  voucher_no: data.voucher_no,
                },
                Remarks: { Against: data.against, Remarks: data.remarks },
                Debit: data.debit,
                Credit: data.credit,
                "Balance(Dr-Cr)": data.balance,
              });
            });
          }
        });
      } else {
        this.$toasted.show("Dowloading Ledger...", {
          theme: "toasted-primary",
          position: "bottom-right",
          duration: 1000,
        });
        axios.defaults.headers.common["Authorization"] =
          "token " + CommonApi.api_key + ":" + CommonApi.api_secret;
        axios({
          url:
            CommonApi.base_url + "customer_self_service.api.portal.get_ledger",
          data,
          method: "POST",
          responseType: "blob", // <= important
        }).then((response) => {
          const url = window.URL.createObjectURL(new Blob([response.data]));
          const link = document.createElement("a");
          link.href = url;
          link.setAttribute("download", "ledger.pdf");
          document.body.appendChild(link);
          link.click();
        });
      }
    },
  },
  mounted() {
    let date = new Date();
    this.enddate = date.toISOString().split("T")[0];
    var firstDay = new Date(date.getFullYear(), date.getMonth(), 1);
    this.startdate = this.convert(firstDay);
    this.get_ledger("false");
  },
};
</script>