<!-- eslint-disable vue/multi-word-component-names -->
<template>
  <div>
    <BreadCrumb title="Notification" :haveButton="true" />
    <div v-if="isSkeletonLoaded">
      <Skeleton />
    </div>
    <div v-if="!isSkeletonLoaded">
      <div class="notification">
        <div class="row">
          <div class="mb-3 mb-lg-0 mr-3 adjust-input">
            <div class="invoice-actions">
              <input
                type="search"
                placeholder="Search..."
                class="form-control form-control-sm"
              />
            </div>
          </div>
          <div class="mb-3 mb-lg-0 mr-3 adjust-input">
            <DatePicker
              lang="en"
              v-model="startdate"
              placeholder="Select Start Date"
              input-class="form-control input-no-border bg-gray-lighter"
            >
            </DatePicker>
          </div>
          <div class="mb-3 mb-lg-0 mr-3 adjust-input">
            <DatePicker
              lang="en"
              v-model="enddate"
              placeholder="Select End Date"
              input-class="form-control input-no-border bg-gray-lighter"
            >
            </DatePicker>
          </div>
          <button class="btn search-button adjust-input">Search</button>
        </div>
      </div>
      <div class="dashboard payment-history notifications mt-3">
        <div>
          <b-card-group deck>
            <b-card>
              <div>
                <b-table
                  responsive
                  :fields="fields"
                  :items="items"
                  @row-clicked="onRowClicked"
                >
                  <template #head(isSelected)>
                    <b-checkbox
                      :checked="isAllSelected"
                      @change="isAllSelected = $event"
                    >
                    </b-checkbox>
                  </template>
                  <template #cell(isSelected)>
                    <b-checkbox :checked="isAllSelected"> </b-checkbox>
                  </template>

                  <template #cell(name)="data">
                    <b class="text-info">{{ data.value.title }}</b>
                  </template>

                  <template slot="row-details"
                    ><b v-html="selectedRowDetails"></b
                  ></template>
                </b-table>
              </div>
            </b-card>
          </b-card-group>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import BreadCrumb from "../../components/breadcrumbs.vue";
import DatePicker from "vue2-datepicker";
import Skeleton from "./notification_skeleton.vue";

export default {
  name: "Notification-Page",
  components: {
    BreadCrumb,
    DatePicker,
    Skeleton,
  },
  data() {
    return {
      startdate: "",
      enddate: "",
      allOpenRows: [],
      selectedRowDetails: "",
      fields: [
        { key: "isSelected" },
        { key: "Title.title", label: "Title" },
        { key: "Date", label: "Date" },
      ],
      filteredItems: [],
      items: [
        {
          id: 1,
          Title: {
            title: "Tracked time has been deleted",
            last: "Your <b>tracked time has been deleted</b>, please find detailed information about deleted periods below:<br><br>Jul 14 16:11 - Jul 14 16:21,<br>Jul 14 16:20 - Jul 14 16:30<br><br><small>Tracked time was deleted from this IP: 122.170.57.243</small>",
          },
          Date: "Jul 14,2022",
        },
        {
          id: 2,
          Title: {
            title: "New project 'Customer Portal' is assigned to you",
            last: "'Nesscale Solution'  has assigned you 'Customer Portal'  project, (Weekly Limit-25 hrs, Screenshot settings-)",
          },
          Date: "Jul 14,2022",
        },
        {
          id: 3,
          Title: {
            title: "You are invited to 'Nesscale's workspace'",
            last: "Nesscale Solution invites you to 'Nesscale's workspace' as an 'Employee'.",
          },
          Date: "Jul 14,2022",
        },
      ],
      isSkeletonLoaded: false,
    };
  },
  computed: {
    isAllSelected: {
      get() {
        const { items } = this;
        return items.filter((item) => item.isSelected).length === items.length;
      },
      set(value) {
        for (const item of this.items) {
          this.$set(item, "isSelected", value);
        }
      },
    },
  },
  methods: {
    onRowClicked(item) {
      this.allOpenRows.map((ele) => {
        if (ele.id !== item.id && ele._showDetails) {
          this.$set(ele, "_showDetails", !ele._showDetails);
        }
      });
      this.allOpenRows = [];
      this.$set(item, "_showDetails", !item._showDetails);
      this.allOpenRows.push(item);
      this.selectedRowDetails = this.allOpenRows[0].Title.last;
    },
  },
};
</script>