<template>
  <div class="global-container">
    <div class="main-body w-100 desktop-view">
      <div class="form-section">
        <div class="column">
          <div class="card login-form shadow">
            <div class="card-body">
              <div
                class="card-title login-content d-flex justify-content-center"
              >
                <h3 class="mt-3 login-banner">Login</h3>
              </div>

              <div class="card-text">
                <form @submit.prevent="submit_login">
                  <!-- User Name Start -->
                  <div class="form-group mb-4">
                    <label class="mb-2 email-pass-label" for="UserName"
                      >User Name</label
                    >
                    <input
                      type="text"
                      class="form-control"
                      name="UserName"
                      v-model="usr"
                      placeholder="Please enter your User Name"
                      required
                    />
                  </div>
                  <!-- User Name End -->

                  <!-- Password Start -->
                  <div class="form-group mb-2">
                    <label class="mb-2 email-pass-label" for="Password"
                      >Password</label
                    >
                    <input
                      type="password"
                      class="form-control"
                      name="password"
                      v-model="pwd"
                      placeholder="Please enter your password"
                      required
                    />
                  </div>
                  <!-- Password End -->

                  <!-- Login Start -->
                  <div class="form-group mt-4 mb-4 d-flex">
                    <button type="submit" class="btn btn-primary">
                      Login
                    </button>
                    <!-- <a
                      class="forgot-password"
                      @click="navigateTo('/auth/create-password')"
                      >Forgot password?</a
                    > -->
                  </div>
                  <!-- Login End -->

                  <hr />

                  <!-- Having problems Start -->
                  <div class="text-center mt-4">
                    <p class="login-account">
                      Having problems signing in? -
                      <a class="contact-us" target="_blank" href="https://nesscale.com">
                        Contact Us</a
                      >
                    </p>
                  </div>
                  <!-- Having problems End -->
                </form>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="mobile-view">
      <ul class="nav nav-pills mb-3" id="pills-tab" role="tablist">
        <li class="nav-item">
          <a
            class="nav-link login active"
            id="pills-home-tab"
            data-toggle="pill"
            href="#pills-home"
            role="tab"
            aria-controls="pills-home"
            aria-selected="true"
            >Login</a
          >
        </li>
        <!-- <li class="nav-item">
          <a
            class="nav-link create-account"
            id="pills-profile-tab"
            data-toggle="pill"
            href="#pills-profile"
            role="tab"
            aria-controls="pills-profile"
            aria-selected="false"
            >Create Account</a
          >
        </li> -->
      </ul>
      <div class="tab-content" id="pills-tabContent">
        <div
          class="tab-pane fade show active"
          id="pills-home"
          role="tabpanel"
          aria-labelledby="pills-home-tab"
        >
          <div class="heading">Sign In to your account</div>
          <div class="card-text">
            <form @submit.prevent="submit_login">
              <!-- User Name Start -->
              <div class="form-group mt-4">
                <label class="mb-2 email-pass-label" for="UserName"
                  >User Name</label
                >
                <input
                  type="text"
                  class="form-control"
                  name="UserName"
                  v-model="usr"
                  placeholder="Please enter your User name"
                  required
                />
              </div>
              <!-- User Name End -->

              <!-- Password Start -->
              <div class="form-group mb-2">
                <label class="mb-2 email-pass-label" for="Password"
                  >Password</label
                >
                <input
                  type="password"
                  class="form-control"
                  name="password"
                  v-model="pwd"
                  placeholder="Please enter your password"
                  required
                />
              </div>
              <!-- Password End -->

              <!-- Forgot-password Start -->
              <!-- <div class="form-group mb-4 forgot-password">
                <a
                  class="forgot-password"
                  @click="navigateTo('/auth/create-password')"
                  >Forgot password?</a
                >
              </div> -->
              <!-- Forgot-password End -->

              <button type="submit" class="btn w-100 login-button">
                Login
              </button>
            </form>
          </div>
        </div>
        <div
          class="tab-pane fade"
          id="pills-profile"
          role="tabpanel"
          aria-labelledby="pills-profile-tab"
        >
          <div class="heading">Please enter the following to get started</div>
          <div class="card-text">
            <form @submit.prevent="submit_login">
              <!-- Account Number Start -->
              <div class="form-group mt-4">
                <label class="mb-2 email-pass-label" for="Account Number"
                  >Account Number</label
                >
                <input
                  type="text"
                  class="form-control"
                  name="Account Number"
                  placeholder="C-XXX-00-00000"
                  required
                />
              </div>
              <!-- Account Number End -->

              <!-- Birth Date Start -->
              <div class="form-group mb-2">
                <label class="mb-2 email-pass-label" for="Birth Date"
                  >Birth Date</label
                >
                <input
                  type="date"
                  class="form-control"
                  name="Birth Date"
                  placeholder="MM/DD/YYYY"
                  required
                />
              </div>
              <!-- Birth Date End -->

              <!-- SSN Start -->
              <div class="form-group mb-2">
                <label class="mb-2 email-pass-label" for="SSN"
                  >The last 4 digits of your SSN</label
                >
                <input
                  type="password"
                  class="form-control"
                  name="SSN"
                  required
                />
              </div>
              <!-- SSN End -->

              <!-- Continue Start -->
              <div class="form-group mt-5 mb-4 w-100">
                <button type="submit" class="btn login-button">Continue</button>
              </div>
              <!-- Continue End -->
            </form>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>


<script>
import CommonApi from "../services/CommonApi";

export default {
  name: "LoginPage",
  data() {
    return {
      usr: "",
      pwd: "",
    };
  },
  methods: {
    //Navigation to Page
    navigateTo(url) {
      this.$router.push(url);
    },

    //Login API
    async submit_login() {
      this.$swal({
        text: "Logging in...",
        showConfirmButton: false,
        allowOutsideClick: false,
        didOpen: () => {
          this.$swal.showLoading();
        },
      });
      var bodyFormData = new FormData();
      bodyFormData.append("usr", this.usr);
      bodyFormData.append("pwd", this.pwd);
      await CommonApi.post_data(
        "customer_self_service.api.portal.login",
        bodyFormData,
        true
      ).then((res) => {
        if (res.message == "Logged In") {
          var userJson = {
            username: res.full_name,
            user: res.user,
            ...res.key_details,
          };
          localStorage.setItem("userInfo", JSON.stringify(userJson));
          this.$router.push("/dashboard");
          this.$swal.close();
        } else {
          this.$swal.fire({
            icon: "error",
            title: "Error",
            text: res.message,
            showConfirmButton: true,
          });
        }
      });
    },
  },
};
</script>