/* For Cart Params */

const state = {
  cart: localStorage.getItem("cart")
    ? JSON.parse(localStorage.getItem("cart")).cart
    : [],
};

// mutations
const mutations = {
  addCart: (state, payload) => {
    const index = state.cart.findIndex(
      (object) => object.item_code === payload.item_code
    );
    if (index === -1) {
      state.cart.push({
        item_code: payload.item_code,
        item_name: payload.item_name,
        qty: payload.qty,
      });
    } else {
      state.cart[index].qty = parseInt(state.cart[index].qty) + payload.qty;
    }
    var cart = {
      cart: state.cart,
    };
    localStorage.setItem("cart", JSON.stringify(cart));
  },

  removeQty: (state, payload) => {
    const index = state.cart.findIndex(
      (object) => object.item_code === payload.item_code
    );
    if (index !== -1 && payload.qty > 1) {
      state.cart[index].qty = parseInt(state.cart[index].qty) - 1;
    } else {
      state.cart.splice(index, 1);
    }
    var cart = {
      cart: state.cart,
    };
    localStorage.setItem("cart", JSON.stringify(cart));
  },

  addQty: (state, payload) => {
    const index = state.cart.findIndex(
      (object) => object.item_code === payload.item_code
    );
    if (index !== -1) {
      state.cart[index].qty = parseInt(state.cart[index].qty) + 1;
    }
    var cart = {
      cart: state.cart,
    };
    localStorage.setItem("cart", JSON.stringify(cart));
  },
};

// actions
const actions = {
  addCart: (context, payload) => {
    context.commit("addCart", payload);
  },

  removeQty: (context, payload) => {
    context.commit("removeQty", payload);
  },

  addQty: (context, payload) => {
    context.commit("addQty", payload);
  },
};

export default {
  namespaced: true,
  state,
  actions,
  mutations,
};
